/** A source PDF, content-addressed by the sha256 of its bytes. */
export interface PdfResourceEntry {
    hash: string;
    contentType: string;
}
/**
 * Write-SAS Azure Blob URLs the outputs are written to. Each must contain `{index}` exactly once —
 * the server rejects any other count.
 */
export interface PdfUploadTemplates {
    pdfimage: string;
    axtree: string;
}
export interface PdfConversionSource {
    /** 64 lowercase hex characters. Upload the bytes before requesting a conversion. */
    hash: string;
    /** Logged for traceability only — the service never fetches it. */
    originalUrl?: string | null;
}
/** The slice of the document to convert. Omit entirely to convert the whole document. */
export interface PdfConversionWindow {
    /** Absolute zero-based first page. */
    startFrom?: number;
    /** `null` converts to the end; an integer clamps to the document remainder. Zero is rejected. */
    maxPages?: number | null;
}
export interface PdfRasterizationOptions {
    dpi?: number;
}
/** Cache controls. Send `options` only when one is set — the server strips them from the cache key. */
export interface PdfConversionOptions {
    /** Skip the cache lookup, so the job always genuinely converts. */
    noCache?: boolean;
    /** Convert without storing the result, so it cannot be served to a later job. */
    noCacheUpdate?: boolean;
}
/** Drives the completion notification the Autonomous service consumes. Omit for no notification. */
export interface PdfConversionNotifierOptions {
    autonomousEnvName?: string | null;
    /** Opaque to the service — echoed back verbatim in the notification. */
    cprTestContext?: unknown;
    renderStatusTopicId?: string | null;
}
export interface PdfConversionRequest {
    source: PdfConversionSource;
    uploadTemplates: PdfUploadTemplates;
    window?: PdfConversionWindow;
    rasterizationOptions?: PdfRasterizationOptions;
    options?: PdfConversionOptions;
    notifierOptions?: PdfConversionNotifierOptions;
    /** Prefixes the returned job id, e.g. `atnms` yields `atnms-<uuid>`. */
    prefixRenderId?: string;
    /** Routes to the canary worker fleet. */
    useCanary?: boolean;
}
export type StartedPdfConversion = {
    pdfConvJobId: string;
};
export type PdfConversionErrorReason = 'pdf-not-found' | 'pdf-too-large' | 'pdf-unreadable' | 'pdf-password-protected' | 'page-cap-exceeded' | 'start-from-out-of-range' | 'invalid-dpi' | 'job-deadline-exceeded' | 'internal-error' | 'invalid-job-message' | 'job-stalled';
/** A page that produced no image. The axtree still lists it as a failed entry. */
export interface PdfFailedPage {
    page: number;
    error: string;
}
/** Where the outputs landed, SAS-stripped — pair them with your own read credentials. */
export interface PdfConversionOutputs {
    image: {
        /** Retains the `{index}` placeholder; fill it with an absolute page number. */
        urlTemplate: string;
        /** Digits to zero-pad the page number to, e.g. `4` renders page 7 as `0007`. */
        indexWidth: number;
        firstPage: number;
        pageCount: number;
    };
    axtree: {
        /** Already resolved — one file per job, covering that job's window. */
        url: string;
    };
}
export interface ConvertingPdfConversionStatus {
    pdfConvJobId: string;
    status: 'converting';
}
export interface ConvertedPdfConversionStatus {
    pdfConvJobId: string;
    status: 'converted';
    /** Pages in the whole document, constant across a cursor walk. */
    totalPages: number;
    /** Pages this job converted, after windowing and clamping. */
    actualPages: number;
    /** Cursor for the next window; `null` means the document is exhausted. */
    nextStartFrom: number | null;
    chunkSize: number;
    failedPages: PdfFailedPage[];
    outputs: PdfConversionOutputs;
}
export interface ErrorPdfConversionStatus {
    pdfConvJobId: string;
    status: 'error';
    reason: PdfConversionErrorReason;
}
/** Discriminated on `status`; terminal is `converted` or `error`. */
export type PdfConversionStatus = ConvertingPdfConversionStatus | ConvertedPdfConversionStatus | ErrorPdfConversionStatus;
